package com.project7.localmanager;
import java.io.*;import java.util.*;
/** Real yuanbao only. Original same-owner transaction supplies the single write. */
public final class WishChoosePolicy {
 public static final String POLICY="wish-treasure-miss-reset-v1";
 static final String SCOPE="q7WishScope";
 static final class Rejected extends IllegalArgumentException{final int code;Rejected(int code){super("许愿改选未执行");this.code=code;}}
 private WishChoosePolicy(){}
 static int value(byte[]d,String k,int fallback){Integer n=BsonLite.intValue(d,k);return n==null?fallback:n;}
 static int scope(byte[]state)throws IOException{byte[]s=BsonLite.documentValue(state,SCOPE);WishCatalog.need(!BsonLite.keys(state).contains(SCOPE)||s!=null,"scope type");if(s==null)return 1;WishCatalog.need(Integer.valueOf(1).equals(BsonLite.intValue(s,"v"))&&WishCatalog.SHA256.equals(BsonLite.stringValue(s,"hash"))&&POLICY.equals(BsonLite.stringValue(s,"policy")),"scope version");int id=value(s,"id",0);WishCatalog.need(DynamicCatalog.num(WishCatalog.row(WishCatalog.ready().wish,id).get("drawType"))==5,"scope pool");return id;}
 static byte[] scopeDoc(int id){return BsonLite.document("v",1,"hash",WishCatalog.SHA256,"policy",POLICY,"id",id);}
 static List<Integer> choice(byte[]s,int id)throws IOException{List<Integer>a=BsonLite.intArrayValues(s,"ctr");WishCatalog.need(!BsonLite.keys(s).contains("ctr")||a!=null,"choice type");if(a==null||a.isEmpty())return Arrays.asList(id,0,0);WishCatalog.need(a.size()==3&&(a.get(0)==id||a.get(0)==0&&a.get(1)==0&&a.get(2)==0)&&a.get(1)>=0&&a.get(2)>=0,"choice state");return a;}
 static byte[] pair(byte[]state,String key,int id,int n)throws IOException{byte[]a=BsonLite.arrayValue(state,key);List<List<Integer>>next=new ArrayList<>();boolean found=false;if(a!=null)for(byte[]row:LocalResourceEngine.array(a)){List<Integer>p=Arrays.asList(BsonLite.intValue(row,"0"),BsonLite.intValue(row,"1"));WishCatalog.need(p.get(0)!=null&&p.get(1)!=null&&p.get(1)>=0,"pair state");if(p.get(0)==id){WishCatalog.need(!found,"pair duplicate");found=true;next.add(Arrays.asList(id,n));}else next.add(p);}if(!found)next.add(Arrays.asList(id,n));return BsonLite.withProfileArray(state,key,next);}
 static boolean pending(byte[]s)throws IOException{if(Boolean.TRUE.equals(BsonLite.boolValue(s,"iof")))return true;byte[]file=BsonLite.documentValue(s,"q7File");if(file!=null)for(String k:BsonLite.keys(file)){byte[]card=BsonLite.documentValue(file,k);if(!Boolean.TRUE.equals(BsonLite.boolValue(card,"is_open")))return true;}return false;}
 /** Host/startup archive selection seam; no invented RPC. Caller owns publication. */
 public static LocalResourceEngine.Result bindArchiveScope(LocalProfileStore store,String account,int wishId)throws IOException{return BaiyeTransactions.transact(store,account,(before,resources)->bindArchiveScope(before,wishId));}
 static LocalResourceEngine.Result bindArchiveScope(byte[]before,int wishId)throws IOException{WishCatalog c=WishCatalog.ready();Map<?,?>row=WishCatalog.row(c.wish,wishId);WishCatalog.need(DynamicCatalog.num(row.get("drawType"))==5,"archive scope source");byte[]state=LocalDrawEngine.state(before,5);WishCatalog.need(!pending(state),"archive scope pending");int old=scope(state);List<Integer>previous=choice(state,old);byte[]all=BsonLite.documentValue(state,"q7WishArchiveChoices");if(all==null)all=BsonLite.EMPTY_DOCUMENT;all=BsonLite.withProfileInt(all,Integer.toString(old),previous.get(1));Integer target=BsonLite.intValue(all,Integer.toString(wishId));int selected=target==null?0:target;WishCatalog.need(selected>=0&&(selected==0||c.choose.containsKey(selected)&&Integer.valueOf(1).equals(WishCatalog.row(c.choose,selected).get("can_choose"))),"archive prior target");state=BsonLite.withProfileDocument(state,"q7WishArchiveChoices",all);state=BsonLite.withProfileDocument(state,SCOPE,scopeDoc(wishId));state=BsonLite.withProfileArray(state,"ctr",Arrays.asList(wishId,selected,previous.get(2)));LocalResourceEngine.Result result=new LocalResourceEngine.Result(before);LocalDrawEngine.saveState(result,state,5);result.add("syncLuckyDrawActivityData",BsonLite.document("t",5,"d",LocalDrawEngine.state(result.profile,5)));result.add("syncTreasureWishInfo",BsonLite.document("t",5,"tw_id",wishId,"s",step(state,wishId)));return result;}
 static int step(byte[]state,int id)throws IOException{byte[]tw=BsonLite.arrayValue(state,"tw");WishCatalog.need(!BsonLite.keys(state).contains("tw")||tw!=null,"wish step array type");int value=0;boolean found=false;if(tw!=null)for(byte[]p:LocalResourceEngine.array(tw))if(Integer.valueOf(id).equals(BsonLite.intValue(p,"0"))){WishCatalog.need(!found,"wish step duplicate");found=true;Integer n=BsonLite.intValue(p,"1");WishCatalog.need(n!=null&&n>=0,"wish step type");value=n;}return value;}
 public static LocalResourceEngine.Result apply(byte[]before,LocalResourceCatalog resources,byte[]params)throws IOException{
  BaiyeTransactions.document(params);Set<String>keys=new HashSet<>(BsonLite.keys(params));if(!keys.equals(new HashSet<>(Arrays.asList("t","i"))))throw new Rejected(1882);int t=BaiyeTransactions.positive(BsonLite.numericValue(params,"t")),item=BaiyeTransactions.positive(BsonLite.numericValue(params,"i"));if(t!=5)throw new Rejected(1882);
  WishCatalog catalog=WishCatalog.ready();if(!catalog.choose.containsKey(item))throw new Rejected(1883);Map<?,?>target=DynamicCatalog.map(catalog.choose.get(item));if(!Integer.valueOf(1).equals(target.get("can_choose")))throw new Rejected(1883);
  byte[]state=LocalDrawEngine.state(before,t);int id=scope(state);List<Integer>old=choice(state,id);int selected=old.get(1),count=old.get(2);int defaultItem=DynamicCatalog.num(WishCatalog.row(catalog.wish,id).get("treasure_id"));if(item==(selected==0?defaultItem:selected))throw new Rejected(1884);if(pending(state))throw new Rejected(1882);if(count==Integer.MAX_VALUE)throw new Rejected(1882);
  int fee=DynamicCatalog.num(WishCatalog.row(catalog.fees,Math.min(count+1,6)).get("cost"));Integer balance=BsonLite.intValue(before,"yuanbao");if(balance==null||balance<fee)throw new Rejected(1885);
  LocalResourceEngine.Result r=new LocalResourceEngine.Result(BsonLite.withProfileInt(before,"yuanbao",balance-fee));List<Integer>ctr=Arrays.asList(id,item,count+1);state=BsonLite.withProfileArray(state,"ctr",ctr);state=pair(state,"tw",id,0);state=BsonLite.withProfileDocument(state,SCOPE,scopeDoc(id));LocalDrawEngine.saveState(r,state,t);
  LocalResourceEngine.syncCurrencies(r);r.add("syncLuckyDrawActivityData",BsonLite.document("t",t,"d",LocalDrawEngine.state(r.profile,t)));r.add("syncTreasureWishInfo",BsonLite.document("t",t,"tw_id",id,"s",0));r.add("replySetChooseTreasure",BsonLite.document("r",0,"t",t,"i",ctr));return r;
 }
}
